import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Boundary-awareness tests for the Szczecin data pipeline.
 *
 * public/data/cities/szczecin.geojson is generated by scripts/fetch-streets.mjs
 * with a point-in-polygon filter against the administrative boundary of
 * Szczecin (OSM relation 342935), stored in
 * public/data/cities/szczecin-boundary.geojson. These tests pin that contract:
 * every kept street must touch the real city area, and streets outside it
 * (e.g. "Gabriela" in Mierzyn) must not be selectable as game targets.
 */

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

type LonLat = [number, number];
interface StreetFeature {
  type: 'Feature';
  properties: { name: string; highway: string };
  geometry: { type: 'LineString'; coordinates: LonLat[] };
}
interface BoundaryFile {
  type: 'FeatureCollection';
  features: Array<{
    type: 'Feature';
    properties: Record<string, unknown>;
    geometry:
      | { type: 'Polygon'; coordinates: LonLat[][] }
      | { type: 'MultiPolygon'; coordinates: LonLat[][][] };
  }>;
}

const streets = JSON.parse(
  readFileSync(path.join(ROOT, 'public/data/cities/szczecin.geojson'), 'utf8')
) as { type: string; features: StreetFeature[] };
const boundary = JSON.parse(
  readFileSync(path.join(ROOT, 'public/data/cities/szczecin-boundary.geojson'), 'utf8')
) as BoundaryFile;

/** All polygon rings (outer + holes) of the boundary feature, flattened. */
function boundaryRings(): LonLat[][] {
  const geom = boundary.features[0].geometry;
  if (geom.type === 'Polygon') return geom.coordinates;
  return geom.coordinates.flat();
}

function pointOnSegment(p: { lat: number; lon: number }, a: { lat: number; lon: number }, b: { lat: number; lon: number }, eps: number): boolean {
  const cross = (b.lon - a.lon) * (p.lat - a.lat) - (b.lat - a.lat) * (p.lon - a.lon);
  const scale = Math.abs(b.lon - a.lon) + Math.abs(b.lat - a.lat);
  if (scale > 0 && Math.abs(cross) / scale > eps) return false;
  return (
    p.lon >= Math.min(a.lon, b.lon) - eps && p.lon <= Math.max(a.lon, b.lon) + eps &&
    p.lat >= Math.min(a.lat, b.lat) - eps && p.lat <= Math.max(a.lat, b.lat) + eps
  );
}

/** Ray casting (even-odd); points on the boundary count as inside. */
function pointInRing(p: { lat: number; lon: number }, ring: LonLat[]): boolean {
  const eps = 1e-9;
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const a = { lon: ring[j][0], lat: ring[j][1] };
    const b = { lon: ring[i][0], lat: ring[i][1] };
    if (pointOnSegment(p, a, b, eps)) return true;
    const crosses = a.lat > p.lat !== b.lat > p.lat;
    if (crosses && p.lon < ((b.lon - a.lon) * (p.lat - a.lat)) / (b.lat - a.lat) + a.lon) {
      inside = !inside;
    }
  }
  return inside;
}

/** Even-odd point-in-polygon across all rings. */
function pointInBoundary(lon: number, lat: number): boolean {
  const p = { lat, lon };
  let inside = false;
  for (const ring of boundaryRings()) {
    if (pointInRing(p, ring)) inside = !inside;
  }
  return inside;
}

describe('szczecin boundary data', () => {
  it('boundary file is a valid FeatureCollection with one Polygon/MultiPolygon feature', () => {
    expect(boundary.type).toBe('FeatureCollection');
    expect(boundary.features).toHaveLength(1);
    const geom = boundary.features[0].geometry;
    expect(['Polygon', 'MultiPolygon']).toContain(geom.type);
    const rings = boundaryRings();
    expect(rings.length).toBeGreaterThanOrEqual(1);
    for (const ring of rings) {
      // A GeoJSON linear ring needs >= 4 positions and must be closed.
      expect(ring.length).toBeGreaterThanOrEqual(4);
      expect(ring[0]).toEqual(ring[ring.length - 1]);
    }
  });

  it('every street feature has at least one vertex inside the boundary polygon', () => {
    expect(streets.type).toBe('FeatureCollection');
    expect(streets.features.length).toBeGreaterThan(0);
    const outside = streets.features.filter(
      (f) => !f.geometry.coordinates.some(([lon, lat]) => pointInBoundary(lon, lat))
    );
    expect(outside.map((f) => f.properties.name)).toEqual([]);
  });

  it('streets outside Szczecin (e.g. "Gabriela" in Mierzyn) are not present', () => {
    const names = streets.features.map((f) => f.properties.name);
    expect(names).not.toContain('Gabriela');
  });

  it('streets reaching the far districts (beyond lat 53.50 / below 53.35 / east of 14.75) are still present', () => {
    const has = (pred: (c: LonLat) => boolean) =>
      streets.features.some((f) => f.geometry.coordinates.some(pred));
    expect(has(([, lat]) => lat > 53.5)).toBe(true); // Załom / północ
    expect(has(([, lat]) => lat < 53.35)).toBe(true); // Płonia / Śmierdnica / południe
    expect(has(([lon]) => lon > 14.75)).toBe(true); // Jezierzyce / wschód
  });
});
